/* @lc app=leetcode id=2353 lang=kotlin */ class FoodRatings(foods: Array<String>, cuisines: Array<String>, ratings: IntArray, val f2c: Map<String, String> = foods.indices.associate { foods[it] to cuisines[it] }, val f2r: MutableMap<String, Int> = foods.indices.associate { foods[it] to ratings[it] }.toMutableMap(), val c2q: Map<String, java.util.TreeSet<Pair<Int, String>>> = foods.indices.groupBy { cuisines[it] }.mapValues { (_, idxs) -> java.util.TreeSet<Pair<Int, String>>(compareBy({ it.first }, { it.second })).apply { idxs.forEach { add(-ratings[it] to foods[it]) } } }) { fun changeRating(food: String, newRating: Int) = c2q[f2c[food]]?.let { set -> f2r[food]?.let { old -> set.remove(-old to food).also { f2r[food] = newRating }.also { set.add(-newRating to food) } } } fun highestRated(cuisine: String): String = c2q[cuisine]?.first()?.second ?: "" }